-- SupportFlow schema.
--
-- Kept as plain SQL rather than generated by an ORM: the project is small
-- enough that the SQL is the clearest statement of the data model, and it
-- makes the indexes and constraints visible rather than inferred.

PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS agents (
  id      TEXT PRIMARY KEY,
  name    TEXT NOT NULL,
  email   TEXT NOT NULL UNIQUE,
  role    TEXT NOT NULL CHECK (role IN ('agent', 'supervisor', 'admin'))
);

CREATE TABLE IF NOT EXISTS customers (
  id      TEXT PRIMARY KEY,
  name    TEXT NOT NULL,
  email   TEXT NOT NULL UNIQUE,
  company TEXT NOT NULL,
  plan    TEXT NOT NULL CHECK (plan IN ('free', 'pro', 'enterprise')),
  since   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS tickets (
  id          TEXT PRIMARY KEY,
  reference   TEXT NOT NULL UNIQUE,
  subject     TEXT NOT NULL,
  status      TEXT NOT NULL CHECK (status IN ('new','open','pending','resolved','closed')),
  priority    TEXT NOT NULL CHECK (priority IN ('low','normal','high','urgent')),
  channel     TEXT NOT NULL CHECK (channel IN ('email','chat','phone','portal')),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  assignee_id TEXT REFERENCES agents(id),
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  -- Optimistic-concurrency token. Every write bumps it; every write is
  -- conditional on the value the caller last saw.
  version     INTEGER NOT NULL DEFAULT 1
);

CREATE INDEX IF NOT EXISTS idx_tickets_status    ON tickets(status);
CREATE INDEX IF NOT EXISTS idx_tickets_priority  ON tickets(priority);
CREATE INDEX IF NOT EXISTS idx_tickets_assignee  ON tickets(assignee_id);
CREATE INDEX IF NOT EXISTS idx_tickets_updated   ON tickets(updated_at DESC);

CREATE TABLE IF NOT EXISTS ticket_labels (
  ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
  label     TEXT NOT NULL,
  PRIMARY KEY (ticket_id, label)
);

CREATE TABLE IF NOT EXISTS messages (
  id          TEXT PRIMARY KEY,
  ticket_id   TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
  author_kind TEXT NOT NULL CHECK (author_kind IN ('customer','agent','system')),
  author_id   TEXT,
  author_name TEXT NOT NULL,
  body        TEXT NOT NULL,
  internal    INTEGER NOT NULL DEFAULT 0 CHECK (internal IN (0, 1)),
  created_at  TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_messages_ticket ON messages(ticket_id, created_at);

CREATE TABLE IF NOT EXISTS ticket_events (
  id         TEXT PRIMARY KEY,
  ticket_id  TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
  actor_id   TEXT,
  actor_name TEXT NOT NULL,
  kind       TEXT NOT NULL,
  detail     TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_events_ticket ON ticket_events(ticket_id, created_at);

CREATE TABLE IF NOT EXISTS saved_replies (
  id    TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  body  TEXT NOT NULL,
  tags  TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS kb_articles (
  id         TEXT PRIMARY KEY,
  slug       TEXT NOT NULL UNIQUE,
  title      TEXT NOT NULL,
  summary    TEXT NOT NULL,
  body       TEXT NOT NULL,
  tags       TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL
);

-- Full-text search over the knowledge base. `porter` stemming means a search
-- for "refunding" finds an article about "refunds".
CREATE VIRTUAL TABLE IF NOT EXISTS kb_fts USING fts5(
  title, summary, body,
  content = 'kb_articles',
  content_rowid = 'rowid',
  tokenize = 'porter unicode61'
);
